#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10

cd "$(dirname "${BASH_SOURCE[0]}")"
ENV_FILE="config.env"
RESULTS="results.md"

# record "Question" asks for a free-text finding and appends it to results.md.
record() {
  local answer="" extra=""
  printf '  %s%s%s\n  > ' "$BOLD" "$1" "$RESET"
  read -r answer || true
  # A multi-line paste arrives as several lines at once: keep them in this one answer.
  while read -r -t 0.3 extra; do answer+=" $extra"; done
  printf -- '- **%s** %s\n' "$1" "$answer" >> "$RESULTS"
}

banner "Live test: a claude.ai connector signing in through WorkOS AuthKit"
[[ -f "$RESULTS" ]] || printf '# Live test results (issue 102)\n\n' > "$RESULTS"

# Resume support: "./wizard.sh 4" starts at stage 4, using values already saved.
FROM="${1:-1}"
_STAGE_INDEX=$((FROM - 1))
AUTHKIT_DOMAIN=$(_existing AUTHKIT_DOMAIN || true)
PUBLIC_URL=$(_existing PUBLIC_URL || true)

# ── 1 ─────────────────────────────────────────────────────────────────────
if (( FROM <= 1 )); then
stage "WorkOS: account and AuthKit domain"
say "Create a throwaway WorkOS account (or sign in) and stay in the Staging environment."
open_url "https://dashboard.workos.com/"
step "If asked, set up AuthKit with the defaults."
step "Find the AuthKit domain. It looks like https://some-words-12.authkit.app."
note "I could not confirm the menu name from the docs. Look under 'Domains', or on the"
note "Authentication / AuthKit overview page."
ask AUTHKIT_DOMAIN "Paste the AuthKit domain, with https:// and no trailing slash:"
AUTHKIT_DOMAIN="${AUTHKIT_DOMAIN%/}"
[[ "$AUTHKIT_DOMAIN" == https://* ]] || AUTHKIT_DOMAIN="https://$AUTHKIT_DOMAIN"
write_env AUTHKIT_DOMAIN "$AUTHKIT_DOMAIN"
if curl -fsS "$AUTHKIT_DOMAIN/.well-known/oauth-authorization-server" -o authkit-metadata.json; then
  printf '  %s✓%s AuthKit answers; its metadata is saved in authkit-metadata.json\n' "$GREEN" "$RESET"
else
  warn "AuthKit's metadata did not load from that domain. Check the value and re-run."
fi
pause
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
if (( FROM <= 2 )); then
stage "WorkOS: Google only, sign-up off"
step "Left menu: Authentication, then the 'OAuth providers' tab. In the Google row click"
step "'Manage' and enable it. Leave the default staging credentials in place."
step "On the Authentication page, switch off email and password, Magic Auth, and any other"
step "sign-in method, so Google is the only one."
step "Switch off sign-up (new user registration)."
note "The docs say sign-up can be disabled but do not name the toggle. Look on the"
note "Authentication page or under AuthKit settings."
pause "Press Enter when Google is the only method and sign-up is off"
record "Where was the sign-up toggle, and anything else you had to set here?"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
if (( FROM <= 3 )); then
stage "WorkOS: let Claude register by CIMD"
step "Left menu: Connect, then Configuration."
step "Enable 'Client ID Metadata Document'. Leave Dynamic Client Registration OFF for now,"
step "so the first attempt shows whether CIMD alone is enough."
pause "Press Enter when CIMD is on and DCR is off"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
if (( FROM <= 4 )); then
stage "Railway: put the test server on a public address"
say "This deploys the throwaway server in this folder to a new Railway project."
say "It holds no secrets. It may use a little of your Railway credit until you delete it."
if confirm "Sign in to Railway and create a project called workos-live-test?"; then
  if ! railway whoami >/dev/null 2>&1; then
    railway login || { warn "Browser sign-in failed; trying the code-based sign-in instead."; railway login --browserless; } \
      || warn "Could not sign in to Railway. Fix that, then re-run: ./wizard.sh 4"
  fi
  railway status >/dev/null 2>&1 || railway init --name workos-live-test \
    || warn "Could not create the Railway project. Re-run later with: ./wizard.sh 4"
  say "First deploy (creates the service)..."
  railway up --detach || warn "railway up reported an error; check the Railway dashboard"
  say "Asking Railway for a public domain..."
  railway domain || warn "No domain from the CLI. In the Railway dashboard: the service, Settings, Networking, Generate Domain."
else
  warn "Skipped. Put the server on any public HTTPS address yourself before continuing."
fi
ask PUBLIC_URL "Paste the public address, like https://workos-live-test-production.up.railway.app:"
PUBLIC_URL="${PUBLIC_URL%/}"
[[ "$PUBLIC_URL" == https://* ]] || PUBLIC_URL="https://$PUBLIC_URL"
write_env PUBLIC_URL "$PUBLIC_URL"
if confirm "Deploy again so the server knows its own address?"; then
  railway up --detach || warn "railway up reported an error; check the Railway dashboard"
fi
say "Waiting for the server to answer (up to 3 minutes)..."
ok=""
for _ in $(seq 1 36); do
  if curl -fsS "$PUBLIC_URL/.well-known/oauth-protected-resource/mcp" 2>/dev/null | grep -q "$PUBLIC_URL/mcp"; then ok=1; break; fi
  sleep 5
done
if [[ -n "$ok" ]]; then
  printf '  %s✓%s The server is up and points sign-in at AuthKit\n' "$GREEN" "$RESET"
else
  warn "The server did not answer correctly. Check 'railway logs' before going on."
fi
pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
if (( FROM <= 5 )); then
stage "WorkOS: name the server as a resource"
say "Tokens must be issued for this exact address:"
printf '\n      %s%s/mcp%s\n\n' "$BOLD" "$PUBLIC_URL" "$RESET"
step "In the WorkOS dashboard (Connect, Configuration), add it as a 'Resource Indicator'."
step "Open the '...' menu beside it and choose 'Set as default'."
pause "Press Enter when the resource indicator is saved"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
if (( FROM <= 6 )); then
stage "WorkOS: one organization, one invitation"
step "Left menu: Organizations. Create one organization (any name)."
step "Invite ONE Gmail address you control to that organization."
note "The docs do not name the button. Try the organization's Users or Invitations tab."
step "Open the invitation email and accept it by signing in with that same Google account."
pause "Press Enter when the invited account has signed in once"
record "Did accepting the invitation work, and where was the invite button?"
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
if (( FROM <= 7 )); then
stage "claude.ai: add the connector and call the tool"
open_url "https://claude.ai/settings/connectors"
step "Add a custom connector with this URL:  $PUBLIC_URL/mcp"
step "If the dialog asks how Claude identifies itself, pick 'Use Claude's published identity'."
step "Connect, and sign in with the INVITED Google account."
step "In a new chat, ask: \"call the whoami tool and show me the full result\"."
record "Did claude.ai connect and return a sub? (yes/no, and any error text)"
record "What did whoami give for client_id and registered_by?"
if confirm "Did it FAIL to connect with CIMD only?"; then
  step "In WorkOS (Connect, Configuration) also enable Dynamic Client Registration."
  step "Remove the connector in claude.ai, add it again choosing 'Register automatically', retry."
  record "With DCR on: did it connect, and what did whoami give for client_id?"
fi
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
if (( FROM <= 8 )); then
stage "Who gets refused"
say "Test A: a Google account that was never invited."
step "Remove the connector in claude.ai and add it again. At the sign-in page choose a"
step "Google account that was NOT invited."
record "Uninvited account: refused? What did the page say?"
say "Test B: an invitation accepted with a different address."
step "In WorkOS invite a second Gmail address. Open its invitation link, but sign in with"
step "a third Google account that is not the invited address."
record "Invite accepted with a different address: refused or allowed?"
step "Finish by reconnecting the connector with the first invited account and calling whoami."
pause "Press Enter when the connector works again for the invited account"
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
if (( FROM <= 9 )); then
stage "Removing a user"
say "The WorkOS docs say ending AuthKit sessions does NOT end a connector's access, which"
say "is the opposite of what the plan assumes. This stage finds out what really ends it."
step "In WorkOS: open the invited user, deactivate their organization membership, and"
step "revoke their sessions. Do not delete the user yet. Note the time."
step "Wait 7 minutes (tokens last 5), then ask Claude to call whoami again."
record "After deactivating and revoking sessions, 7 minutes later: does whoami still work?"
step "Now delete the user in WorkOS. Wait 7 minutes and call whoami again."
record "After deleting the user, 7 minutes later: does whoami still work?"
note "If it still works, look on the user's page for 'Authorized applications' and remove"
note "Claude there, then try once more."
record "Anything else needed to end access (for example removing the authorized application)?"
fi

# ── 10 ────────────────────────────────────────────────────────────────────
if (( FROM <= 10 )); then
stage "Claude Code over HTTP, and saving the evidence"
step "Invite and sign in a user again if you deleted the only one."
step "In another terminal run:"
printf '\n      claude mcp add --transport http workos-live-test %s/mcp\n\n' "$PUBLIC_URL"
step "Start claude, run /mcp, sign in to workos-live-test, and ask it to call whoami."
record "Claude Code over HTTP: did it work, and what client_id did whoami show?"
record "Anything the admin had to set at WorkOS or Google that the plan must list?"
railway logs > server.log 2>&1 &
logs_pid=$!; sleep 8; kill "$logs_pid" 2>/dev/null || true
note "Server log saved to $(pwd)/server.log"
warn "Leave the Railway project up until the agent has read the results."
say "Afterwards: delete the Railway project in its dashboard (Settings, Danger), remove the"
say "connector in claude.ai, and run: claude mcp remove workos-live-test"
pause
fi

finish
printf '  Results are in %s/%s. Tell the agent the wizard is done.\n\n' "$(pwd)" "$RESULTS"
